import{_ as t,o as n,c as a,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy manuscript and pre-final evidence","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","frontmatter":{"title":"Chainy manuscript and pre-final evidence","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","source":"docs/manuscript-evidence-map.md","category":"Research & evaluation","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/manuscript-evidence-map.md","filePath":"content/docs/manuscript-evidence-map.md"}'),r={name:"content/docs/manuscript-evidence-map.md"};function s(o,e,d,c,l,p){return n(),a("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-manuscript-and-pre-final-evidence">Chainy manuscript and pre-final evidence<a class="header-anchor" href="#chainy-manuscript-and-pre-final-evidence" aria-label="Link to this section">​</a></h1><p><strong>Capstone project title:</strong> Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><p>The user supplied the official outline and three mandatory pre-final requirements on October 5, 2026: manuscript formatting and chapters complete, core system modules functional, and necessary pilot-area evidence/documents. <strong>Pre-final remains November 21, 2026.</strong> The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current GDD</a> defines intended game scope; the <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">readiness plan</a> preserves the final approval gate before development. Document readiness, implemented behavior and accepted school evidence are separate claims. The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/manuscript-evidence-map.html">previous evidence map</a> preserves earlier planning.</p><h2 id="official-outline-supplied-by-the-user">Official outline supplied by the user<a class="header-anchor" href="#official-outline-supplied-by-the-user" aria-label="Link to this section">​</a></h2><p>Front matter: title/system page, approval sheet, acknowledgement, executive summary, table of contents, list of tables, list of figures.</p><ol><li>INTRODUCTION: 1.1 Project Context; 1.2 Purpose and Description; 1.3 Objectives of the Study; 1.4 Scope and Delimitation; 1.5 Significance of the Study.</li><li>REVIEW OF RELATED LITERATURE: 2.1 Related Studies &amp; Literature; 2.2 Technical Background; 2.3 Definition of terms.</li><li>DESIGN AND METHODOLOGY: 3.1 Research Methodology and Design; 3.2 System Development Methodology; 3.2.1 Requirement Analysis; 3.2.2 Requirement Documentation; 3.2.2.1 Software Requirements; 3.2.2.2 Hardware Requirements; 3.2.2.3 Data; 3.2.3 Design of Software; 3.2.4 Development and Testing; 3.2.5 Description of the Prototype; 3.2.6 Implementation Plan; 3.3 Respondents &amp; Population; 3.4 Evaluation Tool; 3.4.1 Statistical tools; 3.4.2 ISO 2010 System Evaluation tools.</li><li>RESULTS AND DISCUSSION: 4.1 Preliminary Evaluation Results; 4.2 System Evaluation Results.</li><li>CONCLUSIONS AND RECOMMENDATIONS: 5.1 Conclusion; 5.2 Recommendations.</li></ol><p>REFERENCES.</p><p>APPENDICES: A Relevant Source Code; B Evaluation Tool or Test Documents; C Sample input/Output/Reports; D Users Guide; E Process/Data/Information Flow; F Screen Layout; G Test Results; H Sample Generated Output; I Pictures showcasing the data gathering, investigation done; J One-Page Curriculum Vitae; K Letters/Turnitin Certification; L User Acceptance Testing (UAT); M Memorandum of Understanding (MOU).</p><p>“ISO 2010” is preserved as supplied. Its intended standard/version or school instrument still needs clarification; do not silently rename it.</p><h2 id="evidence-and-ownership">Evidence and ownership<a class="header-anchor" href="#evidence-and-ownership" aria-label="Link to this section">​</a></h2><p>Sean owns all authored manuscript sections, appendices, guides and evidence reports. The other role owners supply their own artifacts through explicit handoffs; this does not create shared ownership of a task card.</p><table><thead><tr><th>Evidence package</th><th>Required source or handoff</th><th>Completion evidence</th></tr></thead><tbody><tr><td>Chapters I–II and references</td><td>Sherwin&#39;s scope decisions; verified literature and lesson sources</td><td>Reviewed narrative consistent with 39 lessons, nine minigames, required 13-question world reviews and stated limitations</td></tr><tr><td>Chapter III and instruments</td><td>Christian&#39;s technical facts; Sherwin&#39;s confirmed study arrangements; adviser-approved method</td><td>Accurate requirements, architecture, device details, respondents and evaluation procedure with unknowns identified</td></tr><tr><td>Working modules and tests</td><td>Christian&#39;s named build, revision, device checks and recovery records</td><td>Requirement-specific actual results, including failures and retests; a specification is not a passing test</td></tr><tr><td>Screen and asset evidence</td><td>Miguel&#39;s UI artifacts and Luis&#39;s asset/provenance handoffs</td><td>Clearly labeled mockups or actual screenshots, with their source and status</td></tr><tr><td>Chapters IV–V</td><td>Actual preliminary/system evaluation and technical records</td><td>Reproducible analysis and conclusions limited to the available findings</td></tr><tr><td>Front matter and appendices A–H</td><td>School format, source extracts, guide, flows, layouts, test records and outputs</td><td>Required numbering, citations and contents checked against actual artifacts</td></tr><tr><td>Appendices I–M and site documents</td><td>Sherwin&#39;s confirmed permissions and external documents; authorized contributor records</td><td>Required photos, CVs, certification, UAT and MOU actually obtained and handled as permitted</td></tr></tbody></table><p>A heading, checklist item or completed board card does not establish an appendix&#39;s completion. Keep identities, raw participant records and identifying photos/forms in approved restricted storage. Repository records should contain redacted summaries or permitted references.</p><h2 id="unresolved-school-and-session-evidence">Unresolved school and session evidence<a class="header-anchor" href="#unresolved-school-and-session-evidence" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Question</th><th>Needed evidence</th></tr></thead><tbody><tr><td>What does the school&#39;s completion percentage measure?</td><td>Actual scoring criteria and calculation, not a percentage inferred from task counts</td></tr><tr><td>What preliminary/system evaluation is required by pre-final?</td><td>Adviser or school guidance, including the intended “ISO 2010” instrument</td></tr><tr><td>What happened at the November 10 Cryptita Plays session?</td><td>Actual build/session records and permitted observations; the scheduled date does not prove it occurred or passed</td></tr><tr><td>Does community evidence satisfy the pilot-area requirement?</td><td>Explicit school acceptance and required site documents</td></tr><tr><td>Which participants, instruments and analysis are permitted?</td><td>Confirmed protocol, participant criteria, consent/guardian requirements, custodian and retention rules</td></tr><tr><td>Which external appendices must be ready by November 21?</td><td>Confirmed requirements and the actual letters, certifications, UAT or MOU</td></tr></tbody></table><p>Unresolved evidence remains a readiness gap. Do not invent results, approvals, participant counts, statistical significance or a supported-device claim.</p><h2 id="current-drafting-route">Current drafting route<a class="header-anchor" href="#current-drafting-route" aria-label="Link to this section">​</a></h2><p>Use the <a href="/Chainy-Docs/content/docs/manuscript-working-draft.html">working draft</a>, <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current GDD</a>, <a href="/Chainy-Docs/content/docs/technical-design.html">technical design</a>, <a href="/Chainy-Docs/content/docs/hardware-validation.html">device plan</a>, <a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA plan</a>, <a href="/Chainy-Docs/content/docs/user-guide.html">learner guide</a> and <a href="/Chainy-Docs/content/docs/team-delegation.html">role ownership</a>. The game is an offline lesson-collection design with clearly labeled AI simulations. Teacher services, exports and standalone Wordle/BlockMatch are outside its current scope.</p><p>Rebaseline unfinished board work after documentation review, retaining history and protecting integration, device QA, manuscript and rehearsal work. The fixed date does not establish feasibility or waive missing evidence.</p></div>',1)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
